package com.ruoyi.paicli.service;

import com.ruoyi.paicli.domain.*;
import com.ruoyi.system.service.ISysUserService;
import org.springframework.transaction.annotation.Transactional;
import java.nio.file.Files;
import java.time.Instant;
import java.util.*;

/** 离线只读导出的bundle先预检；正式导入、旧ID映射和版本安全回撤均由同一MySQL事务负责。 */
public class PcImportService {
    private final PcStore store;private final PcAccess access;private final PcIdempotency idem;private final PcEvidence evidence;private final PcArtifactService artifacts;private final ISysUserService users;
    public PcImportService(PcStore s,PcAccess a,PcIdempotency i,PcEvidence e,PcArtifactService ar,ISysUserService u){store=s;access=a;idem=i;evidence=e;artifacts=ar;users=u;}
    public List<Map<String,Object>> list(long user,long workspace){access.admin(workspace,user);return store.mapper.list(PcTable.IMPORT_BATCH,workspace,null,null,null).stream().map(store::view).toList();}
    private static PcTable table(String kind){return switch(kind){case "MEMORY","POLICY"->PcTable.MEMORY;case "SESSION"->PcTable.SESSION;case "MESSAGE","LEDGER_EVENT"->PcTable.MESSAGE;case "EVENT"->PcTable.EVENT;case "PROMPT"->PcTable.PROMPT_TEMPLATE;case "TASK"->PcTable.TASK;case "PROVIDER"->PcTable.PROVIDER_CONFIG;case "MODEL"->PcTable.MODEL_CONFIG;case "MCP"->PcTable.MCP_CONFIG;case "SKILL"->PcTable.SKILL_CONFIG;case "BROWSER"->PcTable.BROWSER_CONFIG;case "WECHAT"->PcTable.WECHAT_BINDING;case "INDEX"->PcTable.INDEX_MANIFEST;case "SNAPSHOT"->PcTable.SNAPSHOT;case "EVALUATION"->PcTable.EVALUATION_RUN;case "HARNESS"->PcTable.HARNESS_RUN;case "AUDIT"->PcTable.SECURITY_AUDIT;default->throw PcException.invalid("未知源记录类型："+kind);};}
    private Map<String,Object> bundle(long user,long artifactId){try{var content=artifacts.content(user,artifactId);if(content.size()>16L*1024*1024)throw new PcException(413,"PC_IMPORT_SIZE","迁移bundle超过16MB，请按来源批次分包");return store.json.read(Files.readString(content.file(),java.nio.charset.StandardCharsets.UTF_8));}catch(java.io.IOException e){throw new PcException(422,"PC_IMPORT_CONTENT","无法读取UTF-8离线迁移bundle");}}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> preflight(long user,String key,Map<String,Object> input){return idem.run("user:"+user+":import-preflight",key,input,()->{
        long workspace=PcJson.number(input,"directoryContextId"),artifactId=PcJson.number(input,"artifactId");access.admin(workspace,user);PcRecord artifact=access.resource(PcTable.ARTIFACT,artifactId,user,true,false);if(!Objects.equals(artifact.getDirectoryContextId(),workspace)||!"LEGACY_IMPORT".equals(PcJson.text(store.data(artifact),"purpose")))throw PcException.deny("仅当前用户目录的LEGACY_IMPORT产物可预检");Map<String,Object> source=bundle(user,artifactId),identity=PcJson.object(input,"identityMappings");List<String> conflicts=new ArrayList<>(),warnings=new ArrayList<>(),unmapped=new ArrayList<>();Map<String,Integer> counts=new TreeMap<>();String fingerprint=PcJson.text(source,"sourceFingerprint");if(!fingerprint.matches("[a-f0-9]{64}"))conflicts.add("来源SHA-256指纹缺失");if(!"paicli-legacy-v1".equals(source.get("schemaVersion")))conflicts.add("来源schemaVersion不受支持");boolean containsSecrets=secrets(source);if(containsSecrets)conflicts.add("来源包含明文秘密字段，禁止导入");if(rawImages(source))conflicts.add("来源含图片原始base64，请单独上传图片并明确SHA映射");try{Instant.parse(PcJson.text(source,"exportedAt"));}catch(Exception e){conflicts.add("导出时间须为ISO Instant");}
        Object raw=source.get("records");if(!(raw instanceof List<?> records)||records.size()>10000)conflicts.add("records缺失或超过10000条");else{Set<String> ids=new HashSet<>();for(Object value:records){if(!(value instanceof Map<?,?>)){conflicts.add("源记录不是对象");continue;}Map<String,Object> record=new LinkedHashMap<>();((Map<?,?>)value).forEach((k,v)->record.put(String.valueOf(k),v));String kind=PcJson.text(record,"kind"),legacyId=PcJson.text(record,"legacyId"),owner=PcJson.text(record,"legacyOwnerId");counts.merge(kind,1,Integer::sum);try{table(kind);}catch(PcException e){conflicts.add(e.getMessage());}if(legacyId.isBlank()||legacyId.length()>256||!ids.add(kind+":"+legacyId))conflicts.add("来源ID缺失或重复："+kind+":"+legacyId);if(!(record.get("payload") instanceof Map<?,?>))conflicts.add("payload不是对象："+legacyId);try{Instant.parse(PcJson.text(record,"occurredAt"));}catch(Exception e){conflicts.add("源记录时间非法："+legacyId);}Object target=identity.get(owner);if(target==null){if(!unmapped.contains(owner))unmapped.add(owner);}else try{long uid=Long.parseLong(target.toString());access.owner(workspace,uid);var account=users.selectUserById(uid);if(account==null||!"0".equals(account.getStatus())||!"0".equals(account.getDelFlag()))throw PcException.deny("目标账号未启用");}catch(Exception e){if(!unmapped.contains(owner))unmapped.add(owner);}String wfp=PcJson.text(record,"workspaceFingerprint");if(!wfp.isBlank()&&!wfp.equals(PcJson.text(store.data(access.directory(workspace,user,false)),"rootFingerprint")))conflicts.add("来源目录指纹不同，须独立注册后导入："+legacyId);}
            for(Object value:records)if(value instanceof Map<?,?> record&&record.get("payload") instanceof Map<?,?> payload){for(String ref:List.of("legacySessionId","legacyProviderId"))if(payload.containsKey(ref)&&!ids.contains((ref.equals("legacySessionId")?"SESSION:":"PROVIDER:")+payload.get(ref)))conflicts.add("来源关联ID没有对应记录："+payload.get(ref));}}
        Map<String,Object> attachmentMappings=freezeAttachments(user,workspace,input,source,identity,conflicts);warnings.add("旧运行任务进入待核对，排队任务保持暂停，不自动创建outbox");warnings.add("旧批准、密钥、本机安装路径不授予新环境权限");warnings.add("索引为可重建元数据；附件只接受明确上传后SHA映射，不读取旧路径");Map<String,Object> p=new LinkedHashMap<>();p.put("fingerprint",fingerprint);p.put("sourceArtifactId",String.valueOf(artifactId));p.put("sourceDigest",artifact.getContentHash());p.put("identityMappings",identity);p.put("attachmentMappings",attachmentMappings);p.put("counts",counts);p.put("warnings",warnings);p.put("conflicts",conflicts);p.put("unmappedIdentities",unmapped);p.put("containsSecrets",containsSecrets);p.put("canImport",conflicts.isEmpty()&&unmapped.isEmpty()&&!containsSecrets);PcRecord batch=store.insert(PcTable.IMPORT_BATCH,workspace,user,null,null,null,"IMPORT","PREFLIGHT",null,p);evidence.audit(workspace,user,null,null,"IMPORT_PREFLIGHT",Boolean.TRUE.equals(p.get("canImport"))?"READY":"BLOCKED",Map.of("batchId",batch.getId(),"sourceDigest",artifact.getContentHash()));return store.view(batch);
    });}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> action(long user,long id,long version,String key,String action){return idem.run("user:"+user+":import:"+id+":"+action,key,Map.of("version",version),()->{PcRecord batch=access.resource(PcTable.IMPORT_BATCH,id,user,false,true);access.admin(batch.getDirectoryContextId(),user);access.directory(batch.getDirectoryContextId(),user,true);store.version(batch,version);if(action.equals("REVOKE"))return revoke(batch,user);if(!action.equals("COMMIT")||!batch.getState().equals("PREFLIGHT")||!Boolean.TRUE.equals(store.data(batch).get("canImport")))throw PcException.conflict("仅预检可导入且尚未提交的批次允许提交");Map<String,Object> p=store.data(batch);PcRecord artifact=access.resource(PcTable.ARTIFACT,PcJson.number(p,"sourceArtifactId"),user,true,false);if(!Objects.equals(artifact.getContentHash(),p.get("sourceDigest")))throw PcException.conflict("预检后的源产物哈希已变化");Map<String,Object> source=bundle(user,artifact.getId());if(secrets(source)||rawImages(source))throw PcException.deny("来源含明文秘密或未映射图片原文");List<?> records=(List<?>)source.get("records");Map<String,Object> identity=PcJson.object(p,"identityMappings"),attachmentMappings=p.get("attachmentMappings")==null?Map.of():PcJson.object(p,"attachmentMappings");validateAttachmentMappings(attachmentMappings,batch.getDirectoryContextId());Map<String,PcRecord> mapping=new LinkedHashMap<>();List<Map<String,Object>> imported=new ArrayList<>();
        for(Object value:records){Map<String,Object> record=new LinkedHashMap<>();((Map<?,?>)value).forEach((k,v)->record.put(String.valueOf(k),v));String kind=PcJson.text(record,"kind"),legacyId=PcJson.text(record,"legacyId");PcTable table=table(kind);long owner=Long.parseLong(identity.get(PcJson.text(record,"legacyOwnerId")).toString());access.owner(batch.getDirectoryContextId(),owner);Map<String,Object> payload=new LinkedHashMap<>(PcJson.object(record,"payload"));Long intendedScope=Set.of("MEMORY","POLICY","PROMPT").contains(kind)&&Set.of("PERSONAL","GLOBAL","USER").contains(PcJson.text(payload,"scope").toUpperCase(Locale.ROOT))?null:batch.getDirectoryContextId();String sourceKey="import:"+PcJson.digest(p.get("fingerprint")+":"+Objects.toString(intendedScope,"PERSONAL")+":"+owner+":"+kind+":"+legacyId);PcRecord prior=store.mapper.findKey(table,sourceKey,true);if(prior!=null){if(!Objects.equals(prior.getDirectoryContextId(),intendedScope)||!Objects.equals(prior.getOwnerId(),owner))throw PcException.deny("既有导入映射不属于目标scope用户");if(!Objects.equals(store.data(prior).get("legacyPayloadHash"),store.json.hash(payload)))throw PcException.conflict("同一来源ID已导入不同内容："+legacyId);mapping.put(kind+":"+legacyId,prior);continue;}String originalState=PcJson.text(payload,"status");String state=switch(kind){case "TASK"->Set.of("RUNNING","LEASED","WAITING_APPROVAL","AWAITING_APPROVAL","AWAITING_REVIEW","WAITING","CANCELLING","RECONCILE_REQUIRED").contains(originalState.toUpperCase(Locale.ROOT))?"RECONCILE_REQUIRED":Set.of("COMPLETED","completed","FAILED","failed","CANCELLED","cancelled").contains(originalState)?originalState.toUpperCase(Locale.ROOT):"PAUSED_IMPORTED";case "MEMORY"->Set.of("VERIFIED","PENDING","CONFLICT").contains(originalState)?originalState:"PENDING";case "SESSION"->"HISTORICAL";case "MESSAGE","LEDGER_EVENT"->"APPENDED";case "EVENT"->"IMPORTED_UNVERIFIED";case "AUDIT","EVALUATION","HARNESS"->"IMPORTED_UNVERIFIED";case "INDEX"->"STALE";default->"DISABLED_IMPORTED";};String originalPayloadHash=store.json.hash(payload);payload=new LinkedHashMap<>((Map<String,Object>)mapAttachments(payload,attachmentMappings,owner));payload.put("legacyPayloadHash",originalPayloadHash);payload.put("importBatchId",String.valueOf(id));payload.put("legacyId",legacyId);payload.put("sourceFingerprint",p.get("fingerprint"));payload.put("legacyOccurredAt",record.get("occurredAt"));payload.put("legacyOwnerId",record.get("legacyOwnerId"));payload.put("evidenceComplete",false);if(kind.equals("LEDGER_EVENT")){Map<String,Object> entry=new LinkedHashMap<>(payload);for(String field:List.of("legacySessionId","legacyPayloadHash","importBatchId","legacyId","sourceFingerprint","legacyOccurredAt","legacyOwnerId","evidenceComplete"))entry.remove(field);entry.remove("message");payload.put("_ledger",entry);}if(kind.equals("TASK")){for(var field:Map.of("started_at","startedAt","finished_at","finishedAt","duration_ms","durationMs","updated_at","legacyUpdatedAt").entrySet())if(payload.containsKey(field.getKey()))payload.putIfAbsent(field.getValue(),payload.get(field.getKey()));}if(kind.equals("PROMPT")){payload.put("relativePath",PcPromptService.normalize(PcJson.text(payload,"relativePath")));String content=PcJson.text(payload,"content");if(content.isBlank()||content.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw PcException.invalid("来源提示词缺全文或超限");payload.put("sha256",PcJson.digest(content));payload.put("enabled",false);payload.put("scope",intendedScope==null?"PERSONAL":"PROJECT");}payload.remove("secretRef");payload.remove("trustedHash");payload.remove("manifestApproved");if(kind.equals("SESSION")){payload.put("modelId","0");payload.put("approvalMode","ASK");payload.putIfAbsent("mode","REACT");}if(Set.of("PROVIDER","MODEL","MCP","SKILL","BROWSER","WECHAT").contains(kind))payload.put("enabled",false);if(kind.equals("MEMORY")||kind.equals("POLICY")){payload.putIfAbsent("content",payload.getOrDefault("fact",""));payload.put("fact",payload.get("content"));payload.put("scope",intendedScope==null?"PERSONAL":"PROJECT");if(kind.equals("POLICY")){payload.put("source","IMPORTED_PROJECT_RULE");String path=PcJson.text(payload,"relativePath");if(path.isBlank())path=PcJson.text(payload,"name").equals("PAI.local")?"PAI.local.md":"PAI.md";payload.put("sourcePath",PcPromptService.normalize(path));payload.put("layer",intendedScope==null?"USER_PAI":PcJson.text(payload,"variant").equals("LOCAL_OVERRIDE")||path.endsWith("PAI.local.md")?"LOCAL_PAI":"ROOT_PAI");payload.put("sha256",PcJson.digest(PcJson.text(payload,"content")));payload.put("originalContent",payload.get("content"));payload.put("enabled",false);state="PENDING";}}Long scope=intendedScope;String storedKind=kind.equals("EVENT")?PcJson.text(payload,"type"):kind;if(storedKind.isBlank()||storedKind.length()>64)throw PcException.invalid("来源事件类型缺失或过长");PcRecord row=store.insert(table,scope,owner,null,null,null,storedKind,state,sourceKey,payload);mapping.put(kind+":"+legacyId,row);imported.add(Map.of("table",table.name(),"id",String.valueOf(row.getId()),"version",row.getVersion(),"sourceKey",sourceKey));}
        for(var entry:mapping.entrySet()){PcRecord row=entry.getValue();if(!String.valueOf(id).equals(store.data(row).get("importBatchId")))continue;String kind=entry.getKey().substring(0,entry.getKey().indexOf(':'));PcTable table=table(kind);Map<String,Object> data=store.data(row);if(data.get("legacySessionId")!=null){PcRecord session=mapping.get("SESSION:"+data.get("legacySessionId"));if(session==null||!Objects.equals(session.getOwnerId(),row.getOwnerId()))throw PcException.deny("源会话归属与映射用户不一致");row.setSessionId(session.getId());if(Set.of("MESSAGE","LEDGER_EVENT").contains(kind))row.setParentId(session.getId());}if(data.get("legacyProviderId")!=null)data.put("providerId",String.valueOf(mapping.get("PROVIDER:"+data.get("legacyProviderId")).getId()));if(Set.of("MESSAGE","LEDGER_EVENT","EVENT").contains(kind)){long sequence=data.get("sequence") instanceof Number n?n.longValue():row.getId();row.setSequenceNumber(sequence);if(row.getSessionId()!=null){PcRecord session=store.require(PcTable.SESSION,row.getSessionId(),true);session.setSequenceNumber(Math.max(session.getSequenceNumber(),sequence));store.save(PcTable.SESSION,session,store.data(session));}}store.save(table,row,data);}
        List<Map<String,Object>> versions=imported.stream().map(entry->{PcRecord row=store.require(PcTable.valueOf(entry.get("table").toString()),Long.parseLong(entry.get("id").toString()),false);Map<String,Object> item=new LinkedHashMap<>(entry);item.put("version",row.getVersion());return item;}).toList();p.put("importedRecords",versions);p.put("committedAt",store.clock.instant().toString());p.put("canImport",false);batch.setState("COMMITTED");store.save(PcTable.IMPORT_BATCH,batch,p);evidence.audit(batch.getDirectoryContextId(),user,null,null,"IMPORT_COMMIT","COMMITTED",Map.of("batchId",id,"count",versions.size(),"sourceDigest",p.get("sourceDigest")));return store.view(batch);
    });}
    private Map<String,Object> revoke(PcRecord batch,long user){if(!batch.getState().equals("COMMITTED"))throw PcException.conflict("仅已提交批次可以回撤");Map<String,Object> p=store.data(batch);List<?> records=(List<?>)p.getOrDefault("importedRecords",List.of());List<String> conflicts=new ArrayList<>();for(Object value:records){Map<?,?> ref=(Map<?,?>)value;PcRecord row=store.require(PcTable.valueOf(ref.get("table").toString()),Long.parseLong(ref.get("id").toString()),true);if(row.getVersion()!=Long.parseLong(ref.get("version").toString())||!String.valueOf(batch.getId()).equals(store.data(row).get("importBatchId")))conflicts.add(ref.get("table")+":"+ref.get("id"));}if(!conflicts.isEmpty())throw new PcException(409,"PC_IMPORT_REVOKE_CONFLICT","导入记录存在后续编辑，禁止覆盖："+String.join(",",conflicts));for(Object value:records){Map<?,?> ref=(Map<?,?>)value;PcTable table=PcTable.valueOf(ref.get("table").toString());PcRecord row=store.require(table,Long.parseLong(ref.get("id").toString()),true);row.setState("REVOKED_IMPORT");store.save(table,row,store.data(row));}batch.setState("REVOKED");p.put("revokedAt",store.clock.instant().toString());store.save(PcTable.IMPORT_BATCH,batch,p);evidence.audit(batch.getDirectoryContextId(),user,null,null,"IMPORT_REVOKE","REVOKED",Map.of("batchId",batch.getId(),"count",records.size()));return store.view(batch);}
    private Map<String,Object> freezeAttachments(long user,long workspace,Map<String,Object> input,Map<String,Object> source,Map<String,Object> identity,List<String> conflicts){Map<String,Object> mappings=input.get("attachmentMappings")==null?Map.of():PcJson.object(input,"attachmentMappings");if(mappings.size()>1000)throw PcException.invalid("附件映射超过1000项，请拆分迁移bundle");Map<String,Object> frozen=new LinkedHashMap<>();for(var entry:mappings.entrySet()){String sha=entry.getKey();if(!sha.matches("[a-f0-9]{64}")){conflicts.add("附件映射键须为来源SHA256");continue;}try{PcRecord target=access.resource(PcTable.ARTIFACT,Long.parseLong(entry.getValue().toString()),user,false,false);Map<String,Object> data=store.data(target);if(!Objects.equals(target.getDirectoryContextId(),workspace)||!target.getState().equals("ACTIVE")||!"TURN_IMAGE".equals(data.get("purpose"))||!sha.equals(data.getOrDefault("sourceSha256",data.get("sha256"))))throw PcException.deny("附件目标scope、用途或来源SHA不一致");artifacts.content(target.getOwnerId(),target.getId());frozen.put(sha,Map.of("artifactId",String.valueOf(target.getId()),"version",target.getVersion(),"ownerId",String.valueOf(target.getOwnerId()),"sha256",data.get("sha256"),"size",data.get("size"),"mimeType",data.get("mimeType")));}catch(Exception invalid){conflicts.add("附件映射未通过scope/hash/文件核验："+sha);}}if(source.get("records") instanceof List<?> records)for(Object value:records)if(value instanceof Map<?,?> record){String owner=Objects.toString(identity.get(Objects.toString(record.get("legacyOwnerId"),"")),"");for(String sha:attachmentReferences(record.get("payload"))){Object mapping=frozen.get(sha);if(!(mapping instanceof Map<?,?> target)||!owner.equals(target.get("ownerId")))conflicts.add("来源附件未映射到该记录用户的正式产物："+sha);}}return frozen;}
    private Set<String> attachmentReferences(Object value){Set<String> result=new LinkedHashSet<>();if(value instanceof Map<?,?> map){String reference=Objects.toString(map.get("legacyAttachmentSha256"),"");if(reference.isBlank()&&Set.of("image_artifact","image_omitted").contains(Objects.toString(map.get("type"),"")))reference=Objects.toString(map.get("sha256"),"");if(!reference.isBlank()){if(!reference.matches("[a-f0-9]{64}"))throw PcException.invalid("来源附件引用SHA非法");result.add(reference);}if(map.get("attachments") instanceof List<?> attachments)for(Object item:attachments)if(item instanceof String sha){if(!sha.matches("[a-f0-9]{64}"))throw PcException.invalid("旧附件ID/路径不能直接导入，请明确来源SHA");result.add(sha);}for(Object child:map.values())result.addAll(attachmentReferences(child));}else if(value instanceof List<?> list)for(Object child:list)result.addAll(attachmentReferences(child));return result;}
    private void validateAttachmentMappings(Map<String,Object> mappings,long workspace){for(var entry:mappings.entrySet()){Map<?,?> frozen=(Map<?,?>)entry.getValue();PcRecord artifact=store.require(PcTable.ARTIFACT,Long.parseLong(frozen.get("artifactId").toString()),true);Map<String,Object> data=store.data(artifact);if(!Objects.equals(artifact.getDirectoryContextId(),workspace)||!artifact.getState().equals("ACTIVE")||!Objects.toString(artifact.getOwnerId()).equals(frozen.get("ownerId"))||artifact.getVersion()!=Long.parseLong(frozen.get("version").toString())||!Objects.equals(data.get("sha256"),frozen.get("sha256"))||!Objects.equals(entry.getKey(),data.getOrDefault("sourceSha256",data.get("sha256"))))throw PcException.conflict("预检后附件scope、版本或哈希已改变");artifacts.content(artifact.getOwnerId(),artifact.getId());}}
    private Object mapAttachments(Object value,Map<String,Object> mappings,long owner){if(value instanceof Map<?,?> map){Map<String,Object> result=new LinkedHashMap<>();for(var item:map.entrySet()){Object mapped=mapAttachments(item.getValue(),mappings,owner);if(item.getKey().toString().equals("attachments")&&mapped instanceof List<?> list)mapped=list.stream().map(v->v instanceof Map<?,?> a&&a.get("artifactId")!=null?a.get("artifactId"):v instanceof String sha&&mappings.get(sha) instanceof Map<?,?> a&&String.valueOf(owner).equals(a.get("ownerId"))?a.get("artifactId"):v).toList();result.put(item.getKey().toString(),mapped);}String reference=Objects.toString(map.get("legacyAttachmentSha256"),"");if(reference.isBlank()&&Set.of("image_artifact","image_omitted").contains(Objects.toString(map.get("type"),"")))reference=Objects.toString(map.get("sha256"),"");if(!reference.isBlank()){Object mapping=mappings.get(reference);if(!(mapping instanceof Map<?,?> artifact)||!String.valueOf(owner).equals(artifact.get("ownerId")))throw PcException.deny("来源图片没有该用户的已核验附件映射");result.remove("artifactId");result.remove("storageKey");result.remove("path");result.remove("base64Data");result.remove("imageBase64");result.put("type","image_artifact");for(String field:List.of("artifactId","sha256","size","mimeType"))result.put(field,artifact.get(field));result.put("legacyAttachmentSha256",reference);}return result;}if(value instanceof List<?> list)return list.stream().map(child->mapAttachments(child,mappings,owner)).toList();return value;}
    private boolean secrets(Object value){return PcSecretPolicy.contains(value);}
    private boolean rawImages(Object value){if(value instanceof Map<?,?> map){for(String key:List.of("imageBase64","base64Data","imageData"))if(map.get(key)!=null&&!map.get(key).toString().isBlank())return true;for(Object child:map.values())if(rawImages(child))return true;}else if(value instanceof List<?> list)for(Object child:list)if(rawImages(child))return true;return false;}
}
